const PROMPT_SHINY_ODDS=50;
let promptCatchSaving=false;
function preparePromptShinyCatch(p,e){
  if(e.caught||e.promptCatchCompleted)return false;
  e.promptCatchCompleted=true;
  if(!p||p.custom||!isShinyEligiblePokemon(p)||e.shinySaved||e.shinyCaught)return false;
  const key=`rf_prompt_shiny_v1:${user?.id||"local"}:${isAdminTestMode()?"test":"live"}:${p.id}`;
  let roll=e.promptShinyRoll;
  if(!roll||typeof roll.won!=="boolean"){
    try{roll=JSON.parse(localStorage.getItem(key)||"null")}catch{}
    if(!roll||typeof roll.won!=="boolean")roll={won:Math.random()<1/PROMPT_SHINY_ODDS,at:new Date().toISOString()};
  }
  e.promptShinyRoll=roll;
  try{localStorage.setItem(key,JSON.stringify(roll))}catch{}
  if(!roll.won)return false;
  e.shinyCaught=true;
  e.shinyView="shiny";
  return true;
}
function showPromptShinyPopup(p){
  document.getElementById("promptShinyModal")?.remove();
  const modal=document.createElement("div");
  modal.id="promptShinyModal";
  modal.className="modal open";
  modal.setAttribute("role","dialog");
  modal.setAttribute("aria-modal","true");
  modal.setAttribute("aria-labelledby","promptShinyTitle");
  modal.innerHTML=`<div class="modal-card"><div class="modal-handle"></div><h2 id="promptShinyTitle">✨ Congrats!</h2><p>You also unlocked shiny ${esc(p.name||"Pokémon")}${p.form?" • "+esc(p.form):""}!</p><img src="${esc(safariShinyImageUrl(p))}" alt="Shiny ${esc(p.name||"Pokémon")}" style="display:block;width:180px;max-width:80%;height:180px;object-fit:contain;margin:16px auto"><button class="primary" style="width:100%" type="button">Awesome!</button></div>`;
  const previous=document.activeElement;
  const close=()=>{modal.remove();previous?.focus?.()};
  modal.querySelector("button").addEventListener("click",close);
  modal.addEventListener("keydown",event=>{if(event.key==="Escape")close();if(event.key==="Tab"){event.preventDefault();modal.querySelector("button").focus()}});
  document.body.appendChild(modal);
  modal.querySelector("button").focus();
}
