 });
 if(!saveResult?.ok){
   openPokemon(pokemonId,true);
   toast("That catch was not saved. Your latest cloud progress was reloaded, so nothing newer was overwritten.");
   return;
 }
 const savedEntry=entry(pokemonId);
 invalidateAchievementEvolutionExpert();
 syncAchievementMilestoneNotification();
 if(!wasCaught)await logTeamCatchForPokemon(p,savedEntry);
 const earnedBonus=await syncMyTeamBonusForPokemon(p,!wasCaught);
 const monthlyBonusExtra=await syncMonthlyBonusForPokemon(p,!wasCaught);
 openPokemon(pokemonId);
 if(wasCaught){
   toastWithUndo("Marked uncaught.",async()=>{
     entry(pokemonId).caught=true;
     await saveNow();
     invalidateAchievementEvolutionExpert();
     syncAchievementMilestoneNotification();
     await syncMyTeamBonusForPokemon(p,true);
     await syncMonthlyBonusForPokemon(p,true);
     openPokemon(pokemonId);
     toast("Restored as caught.");
   });
 }else{
   const dolls=joinedFaction()?.slug==="poke-dolls";
   if(promptShinyAwarded)showPromptShinyPopup(p);
   if(savedEntry.shinyCaught&&savedEntry.shinySaved)toast("✨ Shiny caught! Its shiny artwork is now permanently unlocked.");
   else{
     const totalPoints=1+(earnedBonus?1:0)+monthlyBonusExtra;
     if(earnedBonus&&monthlyBonusExtra)toast(dolls?`Caught! 💗 Team + Monthly bonuses: ${totalPoints} hearts!`:`Caught! ⭐ Team + Monthly bonuses: ${totalPoints} points!`);
     else if(monthlyBonusExtra)toast(dolls?`Caught! 💗 Monthly Bonus: ${totalPoints} hearts!`:`Caught! ⭐ Monthly Bonus: ${totalPoints} points!`);
     else toast(earnedBonus?(dolls?"Caught! 💗 Team Pokémon bonus: +2 hearts!":"Caught! ⭐ Team Pokémon bonus: 2 points!"):"Caught!");
   }
 }
 }finally{promptCatchSaving=false}
}
